'use strict';

addRepairKB({id:'godex-gx-industrial',brand:'GoDEX',models:['GX4200i','GX4300i','GX4600i'],category:'工業型／校正／品質／連線',title:'GX4200i/GX4300i/GX4600i｜紙張校正、Ribbon、列印品質、USB/LAN、Drive',severity:'高價值',sources:['godex_family'],summary:'GoDEX GX 工業型遇到定位、Ribbon、品質或連線問題，先用單機 FEED/Test 與紙張校正切開 Sensor，再依品質/Drive/Interface 分流。深入拆機與電氣數值以 GX 專屬 User/Service Manual 為準。',keyFacts:['工業機先確認實際 Media Type、Print Method、Ribbon path 與 Sensor 位置。','本機測試正常但電腦不印，優先查 USB/LAN、Driver、Port、Queue。','固定白線清潔後仍在才提高 Printhead；皺碳/單側淡要同步查壓力、Platen 與走紙。'],engineering:['FEED 不走先分 Motor 有聲/無聲；有聲不走優先 Gear/Platen/耗材阻力。','Sensor 校正失敗時先換已知正常耗材與清潔，再進線束/主板。'],verify:['FEED 一次一張','100 張無跳標','Ribbon 不皺/不斷','本機與 USB/LAN 實際送印均正常'],flow:[['確認耗材與模式','Gap/Mark/Continuous、TT/DT、Ribbon 安裝與紙路。',['正確','已修正'],'先排設定與安裝。'],['紙張校正','清 Sensor、確認位置後執行 Calibration。',['成功','失敗'],'失敗再換正常耗材交叉。'],['本機 Test / Config','不經電腦。',['正常','異常'],'正常優先查 Driver/Interface。'],['品質分流','固定測試圖看整體淡、固定白線、單側淡、皺碳。',['品質正常','整體淡','固定白線','單側淡/皺碳'],'分類後處理。'],['Drive / 連線分流','FEED 不走看 Motor/Gear；LAN 走 Link→IP→Ping→Port；USB 看裝置管理員。',['恢復','仍異常','不適用'],'不要混在一起查。'],['硬體收斂','Sensor、Motor、Printhead、線束、PSU、Mainboard 依結果逐層交叉。',['已修復','需換件'],'主板最後。']]});
